    const seasonal = o.amp * Math.sin((i / 7) * Math.PI * 2 + phase);
    const noise = (rand() * 2 - 1) * o.noise;
    out.push(clamp(o.base + o.trend * i + seasonal + noise, o.min, o.max));
  }
  return out;
}

